/**
 * The curated palette gallery: the browsable catalog behind `/palettes`.
 *
 * The first 200 entries are hand-built (five stops that work together); the
 * rest are generated by scripts/generate-gallery-palettes.mjs from each
 * theme's curated hue pools, with spacing and quality gates so every stop
 * earns its place — the gallery's value is curation either way. Themes group
 * palettes the way people search for them (retro, pastel, …); palette pages
 * deep-link into the generator with `?primary=&secondary=&accent=` so every
 * page is a working starting point, not a static swatch card.
 *
 * User-published projects join this catalog next (the `Project` model already
 * carries `visibility`); until then these seeds are the whole gallery, which
 * is why they must be genuinely good.
 */

import { GENERATED_PALETTES } from "./palettes-generated";
import {
  MINTED_PER_THEME as MINTED_COUNT,
  huePool,
  mintPalette,
  parseMintedSlug,
} from "./palette-mint";

export interface PaletteTheme {
  slug: string;
  name: string;
  tagline: string;
  /** Two honest paragraphs rendered on the collection page. */
  intro: string[];
}

export interface GalleryPalette {
  slug: string;
  theme: string;
  name: string;
  /** Five hex stops, darkest feeling first where the palette has a direction. */
  colors: [string, string, string, string, string];
  /** What the palette is for, in the palette's own words — unique per page. */
  description: string;
  tags: string[];
  /** Set on deterministically minted long-tail entries (see `./palette-mint`). */
  mintedIndex?: number;
}

/** Addressable minted palettes per theme (see `./palette-mint`). */
export { MINTED_COUNT as MINTED_PER_THEME };

const HEX = /^#[0-9a-f]{6}$/i;

export function isGalleryHex(value: string): boolean {
  return HEX.test(value);
}

